/* GCR Trains - independent offline working timetable manager.
   No external API, CDN, tracking, or server required. Data is stored in browser localStorage.
   This is a timetable manager, NOT a feed of actual Roblox train positions. */
(() => {
'use strict';
const STORE='gcr_train_times_services_v1';
const PREFS='gcr_train_times_prefs_v1';
const app=document.getElementById('app');
const LOCATION_BY_ID=new Map(GCR_LOCATIONS.map(l=>[l.id,l]));
const WEEKS=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const CATEGORY_LABEL={passenger:'Passenger',freight:'Freight',ecs:'Empty stock',other:'Other / engineering'};
const STATUS_LABEL={scheduled:'Scheduled',running:'Running',completed:'Completed',cancelled:'Cancelled'};
const STP_LABEL={WTT:'Working timetable',STP:'Short-term plan',VAR:'Variation',CAN:'Cancellation'};
const ICONS={train:'<rect x="4" y="3" width="16" height="15" rx="3"/><path d="M4 12h16M8 18l-2 3m10-3 2 3M8 7h.01M16 7h.01"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 1.7 4 3 9 3s9-1.3 9-3V5M3 12c0 1.7 4 3 9 3s9-1.3 9-3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',edit:'<path d="M12 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7"/><path d="m16 5 3 3-9 9-4 1 1-4z"/>',trash:'<path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',layers:'<rect x="5" y="5" width="14" height="14" rx="1"/><path d="M2 9v12h12M9 2h12v12"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',refresh:'<path d="M20 7V3l-4 4m4 0a8 8 0 1 0 1 8M4 17v4l4-4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8m-8 4h8"/>',printer:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 15h12v7H6z"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>'};
const ico=(n,extra='')=>`<svg class="icon ${extra}" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s,root=document)=>root.querySelector(s);
const today=()=>{const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateObj=s=>new Date((s||today())+'T12:00:00');
const niceDate=s=>{try{return new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(dateObj(s))}catch{return s||''}};
const shortDate=s=>{try{return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(dateObj(s))}catch{return s||''}};
const plusDays=(s,n)=>{let d=dateObj(s);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const download=(name,content,type)=>{const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500)};
const loc=id=>LOCATION_BY_ID.get(id)||null;
const placeName=id=>loc(id)?.name||'Unknown location';
const placeCode=id=>loc(id)?.code||'—';
const resolveLocation=(v)=>{const name=String(v||'').trim().toLowerCase(); if(!name)return null;const matches=GCR_LOCATIONS.filter(x=>x.name.toLowerCase()===name||x.tiploc.toLowerCase()===name||x.code.toLowerCase()===name);return matches.length===1?matches[0]:null};
const parseSafe=(s)=>{try{return JSON.parse(s)}catch{return null}};
const cleanTxt=(x,n=180)=>String(x??'').trim().slice(0,n);
const clone=o=>JSON.parse(JSON.stringify(o));
const newId=()=> 'GCR-'+(typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9));
function load(){try{const raw=parseSafe(localStorage.getItem(STORE));return Array.isArray(raw)?raw.filter(s=>s&&s.id&&Array.isArray(s.stops)):[]}catch{return []}}
let services=load();
let prefs=parseSafe((()=>{try{return localStorage.getItem(PREFS)}catch{return '{}'}})())||{};
let search={date:today(),location:'',destination:'',headcode:'',category:'',stp:'',status:'',mode:'detailed'};
let draft=null;let draftId=null;let toastTimeout=null;
const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(services));return true}catch{toast('Browser storage is unavailable or full. Export a backup to protect your work.','error');return false}};
const persistPrefs=()=>{try{localStorage.setItem(PREFS,JSON.stringify(prefs))}catch{}};
function toast(message,type=''){const old=$('.toast');if(old)old.remove();if(toastTimeout)clearTimeout(toastTimeout);const el=document.createElement('div');el.className='toast '+type;el.innerHTML=`${ico(type==='error'?'info':'check')}<span>${esc(message)}</span>`;document.body.appendChild(el);toastTimeout=setTimeout(()=>el.remove(),4500)}
function go(path){location.hash='#/'+path.replace(/^\//,''); if(location.hash==='#/'+path.replace(/^\//,''))render()}
function getRoute(){const raw=(location.hash||'#/').replace(/^#\/?/,'');const [path='',query='']=raw.split('?');return {path:path||'',parts:path.split('/').filter(Boolean),query:new URLSearchParams(query)}}
function serviceActive(s,date){if(!date||!s.startDate)return false;if(s.scheduleType!=='repeat')return s.startDate===date;if(date<s.startDate||date>(s.endDate||s.startDate))return false;return (s.days||[]).includes(dateObj(date).getDay())}
function stationIndex(s,id){return (s.stops||[]).findIndex(p=>p.locationId===id)}
function primaryTime(p){return p?.dep||p?.arr||'--:--'}
function origin(s){return s.stops?.[0]?.locationId||''}
function destination(s){return s.stops?.[s.stops.length-1]?.locationId||''}
function runData(s,day){const r=s.runs?.[day]||{};return {status:r.status||(s.stp==='CAN'?'cancelled':(s.status||'scheduled')),delayMinutes:r.delayMinutes??s.delayMinutes??0,stops:r.stops||{}}}
function ensureRunData(s,day){if(!s.runs||typeof s.runs!=='object')s.runs={};if(!s.runs[day])s.runs[day]={status:s.stp==='CAN'?'cancelled':'scheduled',delayMinutes:0,stops:{}};return s.runs[day]}
function statusTag(s,day){const r=runData(s,day);const val=r.status;if(val==='cancelled')return '<span class="tag cancelled">Cancelled</span>';if(val==='running'&&Number(r.delayMinutes)>0)return `<span class="tag late">${Math.round(Number(r.delayMinutes))} min late</span>`;return `<span class="tag ${esc(val)}">${esc(STATUS_LABEL[val]||'Scheduled')}</span>`}
function categoryTag(c){return `<span class="tag ${esc(c||'other')}">${esc(CATEGORY_LABEL[c]||'Other / engineering')}</span>`}
function sortServices(a,b,date,lid=''){const ta=primaryTime(lid?a.stops[stationIndex(a,lid)] : a.stops[0]);const tb=primaryTime(lid?b.stops[stationIndex(b,lid)] : b.stops[0]);return ta.localeCompare(tb)||a.headcode.localeCompare(b.headcode)}
function forDate(date){return services.filter(s=>serviceActive(s,date))}
function queryServices(filters){const lid=resolveLocation(filters.location)?.id||'';const dst=resolveLocation(filters.destination)?.id||'';let arr=forDate(filters.date).filter(s=>{
 if(lid && stationIndex(s,lid)<0)return false;
 if(dst && stationIndex(s,dst)<0)return false;
 if(lid&&dst&&stationIndex(s,lid)>=stationIndex(s,dst))return false;
 if(filters.location&&!lid)return false;
 if(filters.destination&&!dst)return false;
 if(filters.headcode&&!`${s.headcode} ${s.uid} ${s.operator} ${s.traction} ${placeName(origin(s))} ${placeName(destination(s))}`.toLowerCase().includes(filters.headcode.toLowerCase().trim()))return false;
 if(filters.category&&s.category!==filters.category)return false;
 if(filters.stp&&s.stp!==filters.stp)return false;
 if(filters.status&&runData(s,filters.date).status!==filters.status)return false;
 return true});
 return arr.sort((a,b)=>sortServices(a,b,filters.date,lid))}
function options(current='',values=[],placeholder='All types'){return `<option value="">${esc(placeholder)}</option>`+values.map(([val,label])=>`<option value="${esc(val)}" ${current===val?'selected':''}>${esc(label)}</option>`).join('')}
function locDatalist(){return `<datalist id="gcr-locations">${GCR_LOCATIONS.map(l=>`<option value="${esc(l.name)}" label="${esc(l.code)} · ${esc(l.tiploc)}"></option>`).join('')}</datalist>`}
function heading(title,subtitle,label,actions=''){return `<div class="page-title-row"><div><div class="eyebrow">${esc(label||'GCR TRAIN INFORMATION')}</div><h1 class="page-title">${esc(title)}</h1><p class="page-subtitle">${esc(subtitle||'')}</p></div>${actions?`<div class="heading-action">${actions}</div>`:''}</div>`}
function panel(title,body,action='',cl=''){return `<section class="panel ${cl}"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`}
function button(text,name,variant=''){return `<button type="button" class="btn ${variant}" data-action="${name}">${text}</button>`}
function globalShell(view,route){const active=route.parts[0]||'home';const navs=[['home','Overview','train'],['search','Search trains','search'],['register','Register train','plus'],['locations','Locations','map'],['headcodes','Headcodes','list'],['data','Data & backup','database']];return `<div class="topstrip"></div><header class="site-header"><div class="header-inner"><a href="#/" class="brand"><span class="brand-icon" aria-hidden="true">≋</span><span class="brand-wordmark"><strong>GCR <span>TRAINS</span></strong><small>RAILWAY TIMETABLE INFORMATION</small></span></a><nav class="nav" id="site-nav" aria-label="Main navigation">${navs.map(([path,title,iconName])=>`<a href="#/${path==='home'?'':path}" class="nav-link ${(active===path||active===''&&path==='home'||active==='service'&&path==='search')?'active':''}">${ico(iconName)}${title}</a>`).join('')}</nav><div class="header-actions"><span class="mini-count">${services.length} schedules saved</span><button class="nav-toggle" aria-label="Toggle navigation" data-action="toggle-nav">☰</button></div></div></header><div class="subbar"><div class="subbar-inner"><div class="crumbs">GCR network <span>›</span> ${esc(({home:'Overview',search:'Detailed search',service:'Train information',register:'Register / edit service',locations:'Locations directory',headcodes:'Headcode planning',data:'Data management'})[active]||'Overview')}</div><div class="offline"><i class="status-dot"></i> LOCAL MODE · NO EXTERNAL CONNECTION</div></div></div><main class="container">${view}</main><footer class="footer"><div class="footer-inner"><div><strong>GCR Trains</strong><p>Independent timetable manager for the GCR Roblox railway network.<br>Inspired by the layout of railway timetable search websites; not affiliated with Realtime Trains.</p></div><div class="footer-links"><a href="#/search">Detailed search</a><a href="#/locations">Location codes</a><a href="#/data">Back up timetable</a></div></div></footer><div id="modal-root"></div>${locDatalist()}`}
function emptyState(label='No matching trains',message='No services have been registered for these search conditions.',showButton=true){return `<div class="empty"><div class="empty-icon">${ico('train')}</div><h3>${esc(label)}</h3><p>${esc(message)}</p>${showButton?`<a href="#/register" class="btn primary">${ico('plus')} Register a train</a>`:''}</div>`}
function boardRows(rows,day,lid=''){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>${lid?'WTT':'Departs'}</th><th>Headcode</th><th>Origin</th><th>Destination</th><th>Service</th><th>STP</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(s=>{const p=lid?s.stops[stationIndex(s,lid)]:s.stops[0];return `<tr><td class="mono time-big">${esc(primaryTime(p))}</td><td><a class="headcode-link mono" href="#/service/${encodeURIComponent(s.id)}?date=${day}">${esc(s.headcode)}</a><div class="discreet mono">${esc(s.uid||'')}</div></td><td><a class="station-name" href="#/search?location=${encodeURIComponent(placeName(origin(s)))}&date=${day}">${esc(placeName(origin(s)))}</a></td><td><a class="station-name" href="#/search?location=${encodeURIComponent(placeName(destination(s)))}&date=${day}">${esc(placeName(destination(s)))}</a></td><td>${categoryTag(s.category)}</td><td><span class="tag ${(s.stp||'WTT').toLowerCase()}">${esc(s.stp||'WTT')}</span></td><td>${statusTag(s,day)}</td><td><a href="#/service/${encodeURIComponent(s.id)}?date=${day}" title="View train">${ico('chevron')}</a></td></tr>`}).join('')}</tbody></table></div>`}
function dashboard(){const date=today();const todays=forDate(date).sort((a,b)=>sortServices(a,b,date));const frequent=[GCR_LOCATIONS.find(l=>l.name==='Bessbridge'),GCR_LOCATIONS.find(l=>l.name==='Renford Central'),GCR_LOCATIONS.find(l=>l.name==='Leathminster'),GCR_LOCATIONS.find(l=>l.name==='Landfield North')].filter(Boolean);return `<section class="hero"><small>GCR network · Roblox operations</small><h1>Find a train. View the timetable.<br>Plan your next working.</h1><p>Detailed railway-style train times, headcodes and calling points across the GCR network. Build and manage your own working timetable, all on your computer.</p><form id="hero-search" class="hero-quick"><input name="location" list="gcr-locations" placeholder="Search a location, TIPLOC or 3-letter code" aria-label="Search a station"><button type="submit" class="btn primary">${ico('search')} Search trains</button><a href="#/register" class="btn navy">${ico('plus')} New service</a></form><span class="hero-tag">WORKING TIMETABLE · GCR</span></section>
<div class="metrics"><article class="metric"><div><h3>Registered trains</h3><strong>${services.length}</strong></div><div class="metric-icon">${ico('train')}</div></article><article class="metric"><div><h3>Trains today</h3><strong>${todays.length}</strong></div><div class="metric-icon">${ico('clock')}</div></article><article class="metric"><div><h3>Network locations</h3><strong>${GCR_LOCATIONS.length}</strong></div><div class="metric-icon">${ico('map')}</div></article><article class="metric"><div><h3>Operators</h3><strong>${new Set(services.map(s=>s.operator).filter(Boolean)).size}</strong></div><div class="metric-icon">${ico('layers')}</div></article></div>
<div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Today's working timetable</h2><p>${esc(niceDate(date))} · All train movements registered locally</p></div><a href="#/search" class="small-link">Detailed search ${ico('arrow')}</a></div>${todays.length?boardRows(todays,date):emptyState('No trains registered for today','Create a service to see it here. Once registered, it is searchable by date, location and headcode.')}<div class="panel-footer">WTT = Working Timetable · STP = Short Term Plan · Train running information is updated manually.</div></section><section class="panel"><div class="panel-head"><h2>Quick location search</h2><a href="#/locations" class="small-link">View all ${GCR_LOCATIONS.length} locations</a></div><div class="panel-body"><p class="helper" style="margin-top:0">Explore services calling at frequently used network locations.</p><div class="recent-locations">${frequent.map(l=>`<a class="quick-chip" href="#/search?location=${encodeURIComponent(l.name)}">${ico('map')} ${esc(l.name)} <span class="mono">${esc(l.code)}</span></a>`).join('')}</div></div></section></div><aside class="stack right-col"><section class="panel accent-panel"><div class="panel-head"><h2>${ico('info')} About local running</h2></div><div class="panel-body"><div class="notice warn"><strong>Manually maintained timetable.</strong> This website does not automatically track Roblox trains. Planned schedules and any running updates are entered by you.</div><p class="helper" style="margin:14px 0 0">Everything is stored in this browser. Export regular backups from Data & backup.</p></div></section><section class="panel"><div class="panel-head"><h2>Headcode reference</h2><a href="#/headcodes" class="small-link">Full guide</a></div><div class="panel-body"><div class="headcode-mini">${GCR_HEADCODE_CLASSES.map(([c,label])=>`<a class="hc" href="#/headcodes" title="${esc(label)}"><strong>${esc(c)}</strong><span>CLASS</span></a>`).join('')}</div><p class="helper" style="margin-bottom:0;margin-top:14px">Headcode class and destination-letter conventions are taken from the supplied Headcode Planning tab.</p></div></section><section class="panel"><div class="panel-head"><h2>Network overview</h2></div><div class="panel-body"><div class="stat-list"><div class="stat-line"><span>Stations / junctions</span><strong>76</strong></div><div class="stat-line"><span>Yards / depots / sidings</span><strong>24</strong></div><div class="stat-line"><span>3-letter codes</span><strong>100 entries</strong></div><div class="stat-line"><span>Source</span><strong>Headcode Planning</strong></div></div></div></section></aside></div>`}
function searchPage(){const r=queryServices(search);const place=resolveLocation(search.location);const d=search.date;return `${heading('Detailed train search','Find registered passenger, freight, ECS and other workings using railway-style timetable filters.','SEARCH THE GCR NETWORK',`<a class="btn primary" href="#/register">${ico('plus')} Register a train</a>`)}<div class="grid-main wide"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>${place?'Train movements at '+esc(place.name):'Train search results'}</h2><p>${esc(niceDate(d))} · ${r.length} matching service${r.length===1?'':'s'}</p></div><div class="head-actions"><button class="btn small" data-action="export-results">${ico('download')} CSV</button></div></div>${r.length?boardRows(r,d,place?.id||''):emptyState('No matching services',services.length?'Try another date, station or headcode, or register a new train.':'No trains have been registered yet. Create your first service to populate the timetable.')}<div class="panel-footer">Times shown are booked working timetable times (WTT), not automatic live train observations.</div></section></div><aside class="stack right-col"><section class="panel accent-panel"><div class="panel-head"><h2>${ico('filter')} Search options</h2></div><div class="search-tabs"><button data-action="search-mode" data-mode="simple" class="${search.mode==='simple'?'active':''}">Simple</button><button data-action="search-mode" data-mode="detailed" class="${search.mode==='detailed'?'active':''}">Detailed</button></div><div class="panel-body"><form id="search-form"><div class="search-fields"><div class="field"><label for="search-date">Date</label><input id="search-date" class="input" type="date" name="date" value="${esc(search.date)}" required></div><div class="field"><label for="search-location">Location / station</label><input id="search-location" class="input" name="location" list="gcr-locations" placeholder="All locations" value="${esc(search.location)}"></div><div class="field"><label for="search-destination">Calls later at</label><input id="search-destination" class="input" name="destination" list="gcr-locations" placeholder="Optional destination" value="${esc(search.destination)}"></div>${search.mode==='detailed'?`<div class="field"><label for="search-headcode">Headcode, UID or operator</label><input id="search-headcode" class="input" name="headcode" placeholder="e.g. 6M45" value="${esc(search.headcode)}"></div><div class="field"><label for="search-category">Service type</label><select id="search-category" class="select" name="category">${options(search.category,Object.entries(CATEGORY_LABEL),'All services')}</select></div><div class="field"><label for="search-stp">STP indicator</label><select id="search-stp" class="select" name="stp">${options(search.stp,Object.entries(STP_LABEL),'All indicators')}</select></div><div class="field"><label for="search-status">Running status</label><select id="search-status" class="select" name="status">${options(search.status,Object.entries(STATUS_LABEL),'All statuses')}</select></div>`:''}</div><button type="submit" class="btn primary search-button">${ico('search')} Search trains</button><button type="button" data-action="reset-search" class="btn ghost search-button">Clear filters</button></form></div></section><section class="panel"><div class="panel-head"><h2>Dates</h2></div><div class="panel-body"><div class="calendar-bar"><button class="btn small" data-action="date-prev" aria-label="Previous day">${ico('back')}</button><span class="datebar">${esc(shortDate(search.date))}</span><button class="btn small" data-action="date-next" aria-label="Next day">${ico('chevron')}</button></div></div></section></aside></div>`}
function draftNew(){const d=today();return {id:'',uid:'',headcode:'',operator:'',category:'freight',traction:'',formation:'',scheduleType:'once',startDate:d,endDate:plusDays(d,30),days:[1,2,3,4,5],stp:'WTT',status:'scheduled',delayMinutes:0,notes:'',stops:[{locationId:'',locationText:'',arr:'',dep:'',platform:'',line:'',path:'',activity:'',actualArr:'',actualDep:''},{locationId:'',locationText:'',arr:'',dep:'',platform:'',line:'',path:'',activity:'',actualArr:'',actualDep:''}]}}
function normalizeDraft(s){const result={...draftNew(),...clone(s)};result.stops=(s.stops||[]).map(st=>({...st,locationText:placeName(st.locationId)==='Unknown location'?'':placeName(st.locationId)}));return result}
function ensureDraft(id=''){if(draft&&draftId===id)return;draftId=id;const s=id?services.find(s=>s.id===id):null;draft=s?normalizeDraft(s):draftNew()}
const FIELDS=[['headcode','Headcode','text','e.g. 6M45'],['uid','Unique train ID','text','Auto-generated if blank'],['operator','Train operator','text','e.g. Mercia Rail Haulage Operations'],['traction','Locomotive / unit','text','e.g. 37057, Class 68'],['formation','Train formation / load','text','e.g. 10 loaded wagons'],['notes','Service notes','text','Additional remarks']];
function textField(name,label,placeholder='',extra=''){return `<div class="field"><label for="draft-${name}">${esc(label)}</label><input class="input" id="draft-${name}" name="${name}" data-field="${name}" placeholder="${esc(placeholder)}" value="${esc(draft[name])}" ${extra}></div>`}
function selectField(name,label,values){return `<div class="field"><label for="draft-${name}">${esc(label)}</label><select class="select" id="draft-${name}" data-field="${name}">${values.map(([value,title])=>`<option value="${esc(value)}" ${draft[name]===value?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`}
function weekdayMarkup(){return `<div class="weekdays">${WEEKS.map((d,i)=>`<label class="weekday"><input type="checkbox" data-weekday="${i}" ${(draft.days||[]).includes(i)?'checked':''}>${d}</label>`).join('')}</div>`}
function editorStopRows(){return draft.stops.map((s,i)=>`<tr><td><span class="serial">${i+1}</span></td><td><input class="input loc-input" data-stop="${i}" data-sfield="locationText" list="gcr-locations" placeholder="Search a location" aria-label="Location ${i+1}" value="${esc(s.locationText||placeName(s.locationId).replace('Unknown location',''))}"></td><td><input class="input time-input mono" data-stop="${i}" data-sfield="arr" type="time" aria-label="Arrival time ${i+1}" value="${esc(s.arr)}"></td><td><input class="input time-input mono" data-stop="${i}" data-sfield="dep" type="time" aria-label="Departure time ${i+1}" value="${esc(s.dep)}"></td><td><input class="input narrow-input" data-stop="${i}" data-sfield="platform" maxlength="6" placeholder="—" aria-label="Platform ${i+1}" value="${esc(s.platform)}"></td><td><input class="input narrow-input" data-stop="${i}" data-sfield="line" maxlength="10" placeholder="—" aria-label="Line ${i+1}" value="${esc(s.line)}"></td><td><input class="input narrow-input" data-stop="${i}" data-sfield="path" maxlength="10" placeholder="—" aria-label="Path ${i+1}" value="${esc(s.path)}"></td><td><input class="input narrow-input" data-stop="${i}" data-sfield="activity" maxlength="16" placeholder="T / U / D" aria-label="Activity ${i+1}" value="${esc(s.activity)}"></td><td><div style="display:flex;gap:3px"><button type="button" class="btn small icon-only" data-action="move-stop-up" data-index="${i}" aria-label="Move stop up" ${i===0?'disabled':''}>${ico('up')}</button><button type="button" class="btn small icon-only" data-action="move-stop-down" data-index="${i}" aria-label="Move stop down" ${i===draft.stops.length-1?'disabled':''}>${ico('down')}</button><button type="button" class="btn small icon-only danger" data-action="remove-stop" data-index="${i}" aria-label="Remove stop" ${draft.stops.length<=2?'disabled':''}>${ico('trash')}</button></div></td></tr>`).join('')}
function registerPage(editId=''){ensureDraft(editId);const edit=!!editId;const s=edit?services.find(x=>x.id===editId):null;if(edit&&!s)return missingPage();return `${heading(edit?'Edit train service':'Register a new train','Add a scheduled working to the GCR network. Its full timetable will be searchable by headcode, date and calling points.',edit?'SERVICE EDITOR':'CREATE A WORKING',`<a href="#/${edit?'service/'+encodeURIComponent(editId):''}" class="btn">${ico('back')} ${edit?'Back to train':'Back to overview'}</a>`)}<div class="grid-main"><div class="stack"><form id="service-form" class="panel"><div class="form-section"><div class="section-index"><span class="number">1</span><div><h3>Train identification</h3><p>Headcode, operator, working type and traction.</p></div></div><div class="field-grid three">${textField('headcode','Train headcode *','e.g. 6M45','required maxlength="4" pattern="[0-9][A-Za-z][0-9]{2}" title="Use a four-character headcode, e.g. 6M45"')}${textField('uid','Service UID','Automatically generated if empty')}${selectField('category','Service category',Object.entries(CATEGORY_LABEL))}${textField('operator','Train operating company *','e.g. Mercia Rail Haulage Operations','required')}${textField('traction','Loco / unit number','e.g. 37057')}${textField('formation','Formation / load','e.g. 12 loaded wagons')}${selectField('stp','STP indicator',Object.entries(STP_LABEL))}</div></div><div class="form-section"><div class="section-index"><span class="number">2</span><div><h3>Operating dates</h3><p>Run once or repeat on the selected days of the week.</p></div></div><div class="field-grid three">${selectField('scheduleType','Schedule type',[['once','Single date'],['repeat','Repeating weekly']])}<div class="field"><label for="draft-startDate">${draft.scheduleType==='once'?'Operating date':'First operating date'} *</label><input id="draft-startDate" class="input" type="date" data-field="startDate" value="${esc(draft.startDate)}" required></div><div id="repeat-end" class="field ${draft.scheduleType==='once'?'hidden':''}"><label for="draft-endDate">Last operating date *</label><input id="draft-endDate" class="input" type="date" data-field="endDate" value="${esc(draft.endDate)}"></div><div class="field full ${draft.scheduleType==='once'?'hidden':''}" id="repeat-days"><label>Days of operation *</label>${weekdayMarkup()}<span class="hint">Select the days on which the service runs, within the start and end dates.</span></div></div></div><div class="form-section"><div class="section-index"><span class="number">3</span><div><h3>Calling points and timings</h3><p>Enter at least an origin and destination. Include junctions, passing points, stations and yards as required.</p></div></div><div class="notice" style="margin-bottom:15px">Origin is the first timing point; destination is the last. Use <strong>arrival</strong> and <strong>departure</strong> for stations, or just one time for a passing point. All 100 locations are available.</div><div class="timing-editor-wrap"><table class="editor-table"><thead><tr><th>#</th><th>Location *</th><th>Arr.</th><th>Dep.</th><th>Plat.</th><th>Line</th><th>Path</th><th>Activity</th><th>Arrange</th></tr></thead><tbody id="editor-stops">${editorStopRows()}</tbody></table></div><button class="btn small" type="button" data-action="add-stop">${ico('plus')} Add timing point</button><p class="helper">TIPLOC codes are retained for each location. When three-letter codes are shared by multiple locations, select the full name.</p></div><div class="form-section"><div class="section-index"><span class="number">4</span><div><h3>Additional information</h3><p>Optional service description and operational remarks.</p></div></div><div class="field"><label for="draft-notes">Operating notes</label><textarea id="draft-notes" class="textarea" data-field="notes" placeholder="Details of the working, train load, restrictions, etc.">${esc(draft.notes)}</textarea></div></div><div id="form-validation" class="validation hidden"></div><div class="form-actions"><button class="btn" type="button" data-action="cancel-form">Cancel</button><button type="submit" class="btn primary">${ico('check')} ${edit?'Save changes':'Register train'}</button></div></form></div><aside class="stack right-col"><section class="panel accent-panel"><div class="panel-head"><h2>Working timetable guide</h2></div><div class="panel-body"><ul class="form-side-guide"><li><strong>Headcode</strong><br>Four characters, such as <span class="mono">6M45</span> or <span class="mono">1B02</span>.</li><li><strong>WTT</strong><br>Long-term working timetable service.</li><li><strong>STP</strong><br>Short-term planning addition.</li><li><strong>VAR</strong><br>A variation to a booked timetable.</li><li><strong>CAN</strong><br>A cancelled working.</li><li><strong>Booked times</strong><br>These do not automatically change when a train is late.</li></ul><a href="#/headcodes" class="small-link" style="margin-top:14px">View headcode planning guide ${ico('arrow')}</a></div></section><section class="panel"><div class="panel-head"><h2>Route planning</h2></div><div class="panel-body"><p class="helper no-margin">Stations, junctions and sidings are loaded from your <strong>Headcode Planning</strong> sheet. You can add as many intermediate timing points as you need.</p><div class="section-spacer"></div><a href="#/locations" class="btn" style="width:100%">${ico('map')} Browse locations</a></div></section></aside></div>`}
function detailPage(id,day){const s=services.find(x=>x.id===id);if(!s)return missingPage();day=serviceActive(s,day)?day:s.startDate;const run=runData(s,day);const start=s.stops[0],end=s.stops[s.stops.length-1];const rows=s.stops.map((p,i)=>{const actual=run.stops[i]||{};return `<tr><td><span class="stopname">${esc(placeName(p.locationId))}</span><span class="stopcode">${esc(placeCode(p.locationId))} · ${esc(p.locationId)}</span></td><td class="mono bold">${esc(p.arr||'—')}</td><td class="mono bold">${esc(p.dep||'—')}</td><td class="mono ${actual.actualArr?'act':''}">${esc(actual.actualArr||'—')}</td><td class="mono ${actual.actualDep?'act':''}">${esc(actual.actualDep||'—')}</td><td class="mono">${esc(p.platform||'—')}</td><td class="mono">${esc(p.line||'—')}</td><td class="mono">${esc(p.path||'—')}</td><td class="mono muted">${esc(p.activity|| (i===0?'Origin':i===s.stops.length-1?'Destination':'—'))}</td><td><button class="report-click" data-action="report-stop" data-id="${esc(s.id)}" data-day="${esc(day)}" data-index="${i}" title="Enter actual running times">${ico('edit')}</button></td></tr>`}).join('');return `${heading('Train information','Detailed working timetable and optional manually entered actual running times.','SERVICE INFORMATION',`<a href="#/search?date=${esc(day)}" class="btn">${ico('back')} Search results</a><button class="btn" data-action="print">${ico('printer')} Print</button>`)}<div class="detail-hero"><div class="detail-top"><div class="detail-headcode">${esc(s.headcode)}</div><div><h1>${esc(placeName(origin(s)))} to ${esc(placeName(destination(s)))}</h1><p>${esc(s.operator)} · ${esc(niceDate(day))}</p></div><div class="detail-actions">${statusTag(s,day)}</div></div><div class="detail-meta"><div><span>Scheduled departure</span><strong class="mono">${esc(primaryTime(start))}</strong></div><div><span>Scheduled arrival</span><strong class="mono">${esc(end.arr||end.dep||'--:--')}</strong></div><div><span>Unique service ID</span><strong class="mono">${esc(s.uid)}</strong></div><div><span>STP indicator</span><strong>${esc(s.stp||'WTT')} · ${esc(STP_LABEL[s.stp]||STP_LABEL.WTT)}</strong></div></div></div><div class="grid-main"><div class="stack"><section class="panel"><div class="route-head"><div><h3>${esc(placeName(origin(s)))}</h3><small class="mono">${esc(placeCode(origin(s)))}</small></div><div class="route-arrow">➝</div><div><h3>${esc(placeName(destination(s)))}</h3><small class="mono">${esc(placeCode(destination(s)))}</small></div></div><div class="panel-head"><div><h2>Detailed calling points</h2><p>WTT / actual timings · Click the edit icon to report train times</p></div><span class="pill">${s.stops.length} timing points</span></div><div class="table-wrap"><table class="timeline-table"><thead><tr><th>Location</th><th>WTT arr.</th><th>WTT dep.</th><th>Act. arr.</th><th>Act. dep.</th><th>Plat.</th><th>Line</th><th>Path</th><th>Activity</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="panel-footer">Actual times are provided manually by an operator, not received from a Roblox or signalling data feed.</div></section>${s.notes?panel('Operating notes',`<div class="panel-body" style="white-space:pre-wrap;line-height:1.7;font-size:12px">${esc(s.notes)}</div>`):''}</div><aside class="stack right-col"><section class="panel accent-panel"><div class="panel-head"><h2>Service control</h2></div><div class="panel-body"><div class="field"><label for="status-set">Running status</label><select id="status-set" class="select" data-action="change-status" data-id="${esc(s.id)}" data-day="${esc(day)}">${Object.entries(STATUS_LABEL).map(([v,label])=>`<option value="${v}" ${run.status===v?'selected':''}>${label}</option>`).join('')}</select></div><div class="field spaced"><label for="delay-set">Minutes late (manual)</label><input class="input mono" id="delay-set" type="number" min="0" max="1440" value="${esc(run.delayMinutes||0)}" data-action="change-delay" data-id="${esc(s.id)}" data-day="${esc(day)}"></div><div class="notice warn" style="margin-top:14px">These are operator-controlled updates, not automatic live data.</div></div><div class="panel-footer"><a href="#/register?id=${encodeURIComponent(s.id)}" class="btn primary" style="width:100%">${ico('edit')} Edit timetable</a></div></section><section class="panel"><div class="panel-head"><h2>Train details</h2></div><div class="panel-body"><div class="info-grid"><div><span>Operator</span><b>${esc(s.operator||'—')}</b></div><div><span>Type</span><b>${esc(CATEGORY_LABEL[s.category]||'Other')}</b></div><div><span>Locomotive / unit</span><b>${esc(s.traction||'Not allocated')}</b></div><div><span>Formation / load</span><b>${esc(s.formation||'Not specified')}</b></div><div><span>Schedule</span><b>${s.scheduleType==='repeat'?'Repeating weekly':'One-off'}</b></div><div><span>Headcode class</span><b>${esc(GCR_HEADCODE_CLASSES.find(x=>x[0]===s.headcode?.[0])?.[1]||'Unknown')}</b></div></div>${s.scheduleType==='repeat'?`<p class="helper">Runs ${esc((s.days||[]).map(i=>WEEKS[i]).join(', '))} · ${esc(shortDate(s.startDate))} to ${esc(shortDate(s.endDate))}</p>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Manage service</h2></div><div class="panel-body" style="display:grid;gap:9px"><button class="btn" data-action="duplicate-service" data-id="${esc(s.id)}">${ico('copy')} Duplicate timetable</button><button class="btn danger" data-action="delete-service" data-id="${esc(s.id)}">${ico('trash')} Delete this service</button></div></section></aside></div>`}
function directoryRows(query='',category=''){const term=query.trim().toLowerCase();const matches=GCR_LOCATIONS.filter(l=>(!category||l.type===category)&&(!term||`${l.name} ${l.code} ${l.tiploc}`.toLowerCase().includes(term)));return matches.map(l=>`<div class="directory-item"><a href="#/search?location=${encodeURIComponent(l.name)}"><strong>${esc(l.name)}</strong><small>${esc(l.type)}</small></a><div class="right"><span class="station-code">${esc(l.code)}</span><span class="mono discreet">${esc(l.tiploc)}</span></div></div>`).join('')||`<div class="empty" style="grid-column:1/-1">No locations match your search.</div>`}
function locationsPage(){return `${heading('GCR location directory','All 100 stations, junctions, depots, sidings and yards from your spreadsheet, including their three-letter identifiers and TIPLOCs.','NETWORK REFERENCE',`<a href="#/search" class="btn">${ico('search')} Search trains</a>`)}<section class="panel"><div class="panel-head"><div><h2>Stations, yards and timing points</h2><p>76 station and junction entries · 24 depot / siding / yard entries</p></div><span class="pill">100 total</span></div><div class="directory-toolbar"><input id="directory-search" class="input" placeholder="Filter by name, 3-letter code or TIPLOC..." aria-label="Filter locations"><select id="directory-type" class="select">${options('',[['Station / junction','Stations and junctions'],['Depot / siding / yard','Depots, sidings and yards']],'All locations')}</select></div><div class="directory-grid" id="location-list">${directoryRows()}</div><div class="panel-footer">Note: STM and SCS have multiple locations sharing the same three-letter identifier. TIPLOCs remain unique, so select full names when registering services.</div></section>`}
function headcodesPage(){return `${heading('Headcode planning guide','The class digits and letter identifiers below match the Headcode Planning tab in your spreadsheet.','PLANNING REFERENCE',`<a href="#/register" class="btn primary">${ico('plus')} Register service</a>`)}<div class="hc-grid"><section class="panel"><div class="panel-head"><h2>First digit · train classification</h2><span class="pill">0–9</span></div><div class="panel-body">${GCR_HEADCODE_CLASSES.map(([code,description])=>`<div class="hc-row"><span class="hc-digit">${code}</span><div>${esc(description)}</div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Second character · letter identifiers</h2><span class="pill">17 codes</span></div><div class="panel-body">${GCR_HEADCODE_LETTERS.map(([code,description])=>`<div class="hc-row"><span class="hc-digit">${code}</span><div>${esc(description)}</div></div>`).join('')}</div></section></div><div class="section-spacer"></div><section class="panel"><div class="panel-body"><div class="notice">For example, <strong class="mono">6M45</strong> is a Class 6 freight service with the letter M, which your sheet assigns to Gyles Mount. The final two digits identify the individual working. Operators can enter headcodes based on their own service plan.</div><p class="helper" style="margin:13px 0 0">Reference: <a href="${GCR_SOURCE_URL}" target="_blank" rel="noopener noreferrer">Mercia Rail Haulage Operations — Headcode Planning</a>. The guide is a direct planning reference, not a guarantee of how every real-world railway operator classes trains.</p></div></section>`}
function dataPage(){return `${heading('Data management','Back up, restore or export your GCR working timetable. The site keeps your data locally in this browser.','LOCAL STORAGE & BACKUP')}<div class="stack"><div class="notice warn"><strong>Important:</strong> Your saved services are stored in this browser profile. They are not uploaded to Google Sheets or Roblox. Export a JSON backup regularly, especially before clearing browser data, renaming or moving the website file, or changing browsers.</div><section class="panel"><div class="panel-head"><h2>Timetable backups and exports</h2><span class="pill">${services.length} schedules</span></div><div class="panel-body"><div class="data-tools"><div class="data-tool"><h3>${ico('download')} Backup timetable</h3><p>Save all services, recurring dates and manually recorded timings in a portable JSON file.</p><button class="btn primary" data-action="export-json">${ico('download')} Download JSON</button></div><div class="data-tool"><h3>${ico('upload')} Restore backup</h3><p>Load services from a previously exported JSON backup, merging or replacing the current list.</p><button class="btn" data-action="choose-json">${ico('upload')} Import JSON</button><input class="file-hidden" type="file" accept=".json,application/json" id="import-json"></div><div class="data-tool"><h3>${ico('file')} Export CSV</h3><p>Save planned schedules in a spreadsheet-compatible report, one row per train timing point.</p><button class="btn" data-action="export-all-csv">${ico('download')} Download CSV</button></div></div></div></section><section class="panel"><div class="panel-head"><h2>Stored data</h2></div><div class="panel-body"><div class="stat-list"><div class="stat-line"><span>Saved services</span><strong>${services.length}</strong></div><div class="stat-line"><span>Recorded timing points</span><strong>${services.reduce((n,s)=>n+s.stops.length,0)}</strong></div><div class="stat-line"><span>Available GCR locations</span><strong>${GCR_LOCATIONS.length}</strong></div><div class="stat-line"><span>Browser storage</span><strong>On this computer</strong></div></div><div class="section-spacer"></div><button class="btn danger" data-action="clear-data">${ico('trash')} Delete all stored services</button></div></section></div>`}
function missingPage(){return `${heading('Page not found','The requested train service could not be found.','GCR TRAINS')}<section class="panel">${emptyState('Service unavailable','This service may have been deleted or the link is no longer valid.',false)}<div class="panel-footer"><a href="#/search" class="btn">Return to search</a></div></section>`}
function render(){const r=getRoute();const page=r.parts[0]||'home';let view;if(page==='search'){
 if(r.query.has('location'))search.location=r.query.get('location')||'';
 if(r.query.has('date'))search.date=r.query.get('date')||today();
 if(r.query.has('headcode'))search.headcode=r.query.get('headcode')||'';
 // Consume URL params after applying so search filters aren't reset by subsequent state changes.
 if(r.query.toString())history.replaceState(null,'',location.href.split('#')[0]+'#/search');view=searchPage();
}else if(page==='register')view=registerPage(r.query.get('id')||'');else if(page==='service')view=detailPage(decodeURIComponent(r.parts[1]||''),r.query.get('date')||today());else if(page==='locations')view=locationsPage();else if(page==='headcodes')view=headcodesPage();else if(page==='data')view=dataPage();else view=dashboard();app.innerHTML=globalShell(view,r);document.title=(page==='service'?'Train information':({home:'Overview',search:'Detailed search',register:'Train registration',locations:'Locations',headcodes:'Headcode guide',data:'Data management'}[page]||'Overview'))+' | GCR Trains';}
function renderStopsEditor(){const e=$('#editor-stops');if(e)e.innerHTML=editorStopRows()}
function showFormError(text){const el=$('#form-validation');if(!el)return;el.className='validation notice error';el.textContent=text;el.scrollIntoView({behavior:'smooth',block:'center'});}
function saveDraft(){const head=cleanTxt(draft.headcode,4).toUpperCase();if(!/^[0-9][A-Z][0-9]{2}$/.test(head))return showFormError('Please enter a valid four-character headcode such as 6M45.'),false;
 if(!draft.operator?.trim())return showFormError('Enter the name of the train operating company.'),false;
 if(!draft.startDate)return showFormError('Choose an operating date.'),false;
 if(draft.scheduleType==='repeat'){
 if(!draft.endDate||draft.endDate<draft.startDate)return showFormError('The last operating date must be on or after the first operating date.'),false;
 if(!(draft.days||[]).length)return showFormError('Choose at least one day of operation for a repeating timetable.'),false;
 }
 if(draft.stops.length<2)return showFormError('A train needs at least two timing points: an origin and a destination.'),false;
 const cleanStops=[];
 for(let i=0;i<draft.stops.length;i++){
  const p=draft.stops[i];const l=resolveLocation(p.locationText||p.locationId);
  if(!l)return showFormError(`Select a valid, unambiguous network location at timing point ${i+1}. For duplicated codes like STM, use the full location name.`),false;
  if(!p.arr&&!p.dep)return showFormError(`Enter an arrival, departure or passing time at ${l.name}.`),false;
  cleanStops.push({locationId:l.id,arr:cleanTxt(p.arr,5),dep:cleanTxt(p.dep,5),platform:cleanTxt(p.platform,8),line:cleanTxt(p.line,12),path:cleanTxt(p.path,12),activity:cleanTxt(p.activity,25),actualArr:cleanTxt(p.actualArr,5),actualDep:cleanTxt(p.actualDep,5)});
 }
 const existing=draftId?services.find(s=>s.id===draftId):null;
 let newUID=cleanTxt(draft.uid,30).toUpperCase();if(!newUID){let seq=1;do{newUID='GCR'+String(seq++).padStart(5,'0')}while(services.some(s=>s.id!==existing?.id&&s.uid===newUID))}const record={id:existing?.id||newId(),uid:newUID,headcode:head,operator:cleanTxt(draft.operator,120),category:draft.category,traction:cleanTxt(draft.traction,80),formation:cleanTxt(draft.formation,140),scheduleType:draft.scheduleType,startDate:draft.startDate,endDate:draft.scheduleType==='repeat'?draft.endDate:draft.startDate,days:draft.scheduleType==='repeat'?[...draft.days]:[],stp:draft.stp,status:draft.stp==='CAN'?'cancelled':draft.status||'scheduled',delayMinutes:Number(draft.delayMinutes)||0,runs:existing?.runs||{},notes:cleanTxt(draft.notes,3000),stops:cleanStops,createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
 if(services.some(s=>s.id!==record.id&&s.uid===record.uid))return showFormError('The service UID is already in use. Enter another UID or leave it blank.'),false;
 if(existing)services=services.map(s=>s.id===record.id?record:s);else services.push(record);
 persist();draft=null;draftId=null;toast(existing?'Train service updated.':'Train successfully registered.');go('service/'+encodeURIComponent(record.id)+'?date='+record.startDate);return true;
}
function reportStop(id,index,day){const s=services.find(s=>s.id===id);const p=s?.stops?.[index];if(!p)return;const actual=runData(s,day).stops[index]||{};const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="report-title"><div class="modal-header"><h3 id="report-title">Record actual running times</h3><button class="btn icon-only" data-action="close-modal">${ico('close')}</button></div><form id="report-form" data-id="${esc(id)}" data-index="${index}" data-day="${esc(day)}"><div class="modal-body"><p style="margin:0 0 15px"><strong>${esc(s.headcode)}</strong> · ${esc(placeName(p.locationId))}</p><div class="notice warn" style="margin-bottom:17px">Manual report only. This does not update automatically from Roblox.</div><div class="field-grid"><div class="field"><label>Actual arrival</label><input class="input mono" type="time" name="actualArr" value="${esc(actual.actualArr||'')}"></div><div class="field"><label>Actual departure / passing</label><input class="input mono" type="time" name="actualDep" value="${esc(actual.actualDep||'')}"></div></div><p class="helper" style="margin-bottom:0">Leave a field blank if it does not apply to this timing point.</p></div><div class="modal-footer"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${ico('check')} Save actual times</button></div></form></div></div>`;root.querySelector('input')?.focus()}
function closeModal(){const m=$('#modal-root');if(m)m.innerHTML=''}
function serialiseBackup(){return JSON.stringify({format:'GCR-TRAINS-BACKUP',version:1,exportedAt:new Date().toISOString(),sourceSheet:GCR_SOURCE_URL,services},null,2)}
function makeCSV(list){const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=[['Headcode','UID','Operator','Type','STP','Schedule','Start date','End date','Days','Status','Loco / unit','Formation','Stop no','Location','3-letter code','TIPLOC','WTT arrival','WTT departure','Actual arrival','Actual departure','Platform','Line','Path','Activity','Notes']];for(const s of list)for(let i=0;i<s.stops.length;i++){const p=s.stops[i];rows.push([s.headcode,s.uid,s.operator,CATEGORY_LABEL[s.category]||s.category,s.stp,s.scheduleType,s.startDate,s.endDate,(s.days||[]).map(d=>WEEKS[d]).join(' '),s.status,s.traction,s.formation,i+1,placeName(p.locationId),placeCode(p.locationId),p.locationId,p.arr,p.dep,(s.scheduleType==='once'?runData(s,s.startDate).stops[i]?.actualArr:'')||'',(s.scheduleType==='once'?runData(s,s.startDate).stops[i]?.actualDep:'')||'',p.platform,p.line,p.path,p.activity,s.notes])}return '\uFEFF'+rows.map(row=>row.map(quote).join(',')).join('\r\n')}
function sanitizeRuns(runs){const out={};if(!runs||typeof runs!=='object')return out;for(const [date,r] of Object.entries(runs).slice(0,5000)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!r||typeof r!=='object')continue;const stops={};for(const [i,p] of Object.entries(r.stops||{})){if(!/^\d{1,4}$/.test(i)||!p)continue;stops[i]={actualArr:cleanTxt(p.actualArr,5),actualDep:cleanTxt(p.actualDep,5)}}out[date]={status:STATUS_LABEL[r.status]?r.status:'scheduled',delayMinutes:Math.max(0,Number(r.delayMinutes)||0),stops}}return out}
function validImportedService(x){if(!x||typeof x!=='object'||!Array.isArray(x.stops)||x.stops.length<2||!x.headcode||!x.startDate)return null;const stops=x.stops.map(p=>({locationId:cleanTxt(p.locationId,20),arr:cleanTxt(p.arr,5),dep:cleanTxt(p.dep,5),platform:cleanTxt(p.platform,8),line:cleanTxt(p.line,12),path:cleanTxt(p.path,12),activity:cleanTxt(p.activity,25),actualArr:cleanTxt(p.actualArr,5),actualDep:cleanTxt(p.actualDep,5)}));if(stops.some(p=>!loc(p.locationId)))return null;return {id:cleanTxt(x.id,100)||newId(),uid:cleanTxt(x.uid,30),headcode:cleanTxt(x.headcode,4).toUpperCase(),operator:cleanTxt(x.operator,120),category:CATEGORY_LABEL[x.category]?x.category:'other',traction:cleanTxt(x.traction,80),formation:cleanTxt(x.formation,140),scheduleType:x.scheduleType==='repeat'?'repeat':'once',startDate:cleanTxt(x.startDate,10),endDate:cleanTxt(x.endDate||x.startDate,10),days:Array.isArray(x.days)?x.days.filter(v=>Number.isInteger(v)&&v>=0&&v<=6):[],stp:STP_LABEL[x.stp]?x.stp:'WTT',status:STATUS_LABEL[x.status]?x.status:'scheduled',delayMinutes:Math.max(0,Number(x.delayMinutes)||0),notes:cleanTxt(x.notes,3000),runs:sanitizeRuns(x.runs),stops,createdAt:cleanTxt(x.createdAt,40),updatedAt:new Date().toISOString()}}
async function importJSON(file){if(!file)return;try{const text=await file.text();const obj=JSON.parse(text);if(obj.format!=='GCR-TRAINS-BACKUP'||!Array.isArray(obj.services))throw new Error('This is not a GCR Trains backup file.');const imported=obj.services.map(validImportedService);if(imported.some(x=>!x))throw new Error('One or more services are incomplete or reference unknown locations.');const replace=confirm(`${imported.length} service(s) found.\n\nChoose OK to REPLACE all current schedules with this backup.\nChoose Cancel to MERGE these schedules with your existing trains.`);if(replace){if(!confirm('Replace all existing services? This cannot be undone unless you have another backup.'))return;services=imported;}else{const byId=new Map(services.map(s=>[s.id,s]));for(const s of imported)byId.set(s.id,s);services=[...byId.values()]}persist();toast(`Imported ${imported.length} service(s).`);render()}catch(e){toast(e.message||'Could not import this file.','error')}finally{const fileInput=$('#import-json');if(fileInput)fileInput.value=''}}
function downloadJSON(){download('GCR-Trains-backup-'+today()+'.json',serialiseBackup(),'application/json;charset=utf-8');toast('Timetable backup downloaded.')}
function downloadCSV(all=false){const results=all?services:queryServices(search);download('GCR-Trains-'+(all?'all-schedules-':'search-')+today()+'.csv',makeCSV(results),'text/csv;charset=utf-8');toast('CSV export downloaded.')}
function syncDraftInput(el){if(!draft)return;const field=el.dataset.field;if(field){draft[field]=el.value;if(field==='scheduleType'){const repeated=draft.scheduleType==='repeat';$('#repeat-end')?.classList.toggle('hidden',!repeated);$('#repeat-days')?.classList.toggle('hidden',!repeated);const l=$('label[for="draft-startDate"]');if(l)l.textContent=repeated?'First operating date *':'Operating date *';}return}if(el.dataset.sfield){const i=Number(el.dataset.stop);if(draft.stops[i]){draft.stops[i][el.dataset.sfield]=el.value;if(el.dataset.sfield==='locationText'){draft.stops[i].locationId=resolveLocation(el.value)?.id||''}}}if(el.dataset.weekday!==undefined){const d=Number(el.dataset.weekday);const days=new Set(draft.days||[]);if(el.checked)days.add(d);else days.delete(d);draft.days=[...days].sort((a,b)=>a-b)}}
function syncSearchInputs(form){const data=new FormData(form);for(const key of ['date','location','destination','headcode','category','stp','status'])if(form.elements.namedItem(key))search[key]=String(data.get(key)||'');if(!search.date)search.date=today()}
function onClick(e){const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;const id=el.dataset.id;const index=Number(el.dataset.index);const day=el.dataset.day;if(act==='modal-backdrop'){if(e.target===el)closeModal();return}if(act==='toggle-nav'){$('#site-nav')?.classList.toggle('open');return}
 if(act==='search-mode'){search.mode=el.dataset.mode;render();return}
 if(act==='date-prev'||act==='date-next'){search.date=plusDays(search.date,act==='date-prev'?-1:1);render();return}
 if(act==='reset-search'){search={date:today(),location:'',destination:'',headcode:'',category:'',stp:'',status:'',mode:search.mode};render();return}
 if(act==='export-results'){downloadCSV(false);return}
 if(act==='add-stop'){draft.stops.push({locationId:'',locationText:'',arr:'',dep:'',platform:'',line:'',path:'',activity:'',actualArr:'',actualDep:''});renderStopsEditor();return}
 if(act==='remove-stop'){if(draft.stops.length<=2)return;draft.stops.splice(index,1);renderStopsEditor();return}
 if(act==='move-stop-up'||act==='move-stop-down'){const j=index+(act==='move-stop-up'?-1:1);if(j<0||j>=draft.stops.length)return;[draft.stops[index],draft.stops[j]]=[draft.stops[j],draft.stops[index]];renderStopsEditor();return}
 if(act==='cancel-form'){draft=null;const route=draftId?'service/'+encodeURIComponent(draftId):'';draftId=null;go(route);return}
 if(act==='report-stop'){reportStop(id,index,day);return}
 if(act==='close-modal'){closeModal();return}
 if(act==='delete-service'){const s=services.find(x=>x.id===id);if(s&&confirm(`Delete service ${s.headcode} (${s.uid})? This cannot be undone without a backup.`)){services=services.filter(x=>x.id!==id);persist();toast('Service deleted.');go('search')}return}
 if(act==='duplicate-service'){const s=services.find(x=>x.id===id);if(!s)return;const c=clone(s);c.id=newId();c.uid='GCR'+String(services.length+1).padStart(5,'0');while(services.some(x=>x.uid===c.uid))c.uid='GCR'+String(10000+Math.floor(Math.random()*90000));c.createdAt=new Date().toISOString();c.updatedAt=c.createdAt;c.status='scheduled';c.delayMinutes=0;c.runs={};c.stops.forEach(p=>{p.actualArr='';p.actualDep=''});services.push(c);persist();toast('Timetable duplicated.');go('service/'+encodeURIComponent(c.id)+'?date='+c.startDate);return}
 if(act==='print'){window.print();return}
 if(act==='export-json'){downloadJSON();return}
 if(act==='choose-json'){$('#import-json')?.click();return}
 if(act==='export-all-csv'){downloadCSV(true);return}
 if(act==='clear-data'){if(confirm(`Permanently delete all ${services.length} locally saved services? Export a JSON backup first if you want to keep them.`)&&confirm('Final confirmation: delete all registered trains?')){services=[];persist();toast('All registered services deleted.');render()}return}
}
function onChange(e){const el=e.target;if(el.matches('#import-json')){importJSON(el.files?.[0]);return}if(el.matches('#directory-search,#directory-type')){const list=$('#location-list');if(list)list.innerHTML=directoryRows($('#directory-search')?.value||'',$('#directory-type')?.value||'');return}
 if(el.dataset.action==='change-status'||el.dataset.action==='change-delay'){const s=services.find(s=>s.id===el.dataset.id);if(!s)return;const r=ensureRunData(s,el.dataset.day||s.startDate);if(el.dataset.action==='change-status')r.status=el.value;else r.delayMinutes=Math.max(0,Math.min(1440,Number(el.value)||0));s.updatedAt=new Date().toISOString();persist();render();toast('Manual running information saved.');return}
 if(el.dataset.field||el.dataset.sfield||el.dataset.weekday!==undefined)syncDraftInput(el)
}
function onInput(e){const el=e.target;if(el.matches('#directory-search')){const list=$('#location-list');if(list)list.innerHTML=directoryRows(el.value,$('#directory-type')?.value||'');return}if(el.dataset.field||el.dataset.sfield||el.dataset.weekday!==undefined)syncDraftInput(el)}
function onSubmit(e){const f=e.target;if(!['hero-search','search-form','service-form','report-form'].includes(f.id))return;e.preventDefault();if(f.id==='hero-search'){const v=String(new FormData(f).get('location')||'').trim();go('search'+(v?'?location='+encodeURIComponent(v):''));return}
 if(f.id==='search-form'){syncSearchInputs(f);render();return}
 if(f.id==='service-form'){saveDraft();return}
 if(f.id==='report-form'){const s=services.find(x=>x.id===f.dataset.id);const p=s?.stops[Number(f.dataset.index)];if(!p)return;const day=f.dataset.day||s.startDate;const r=ensureRunData(s,day);const fd=new FormData(f);const actualArr=String(fd.get('actualArr')||'');const actualDep=String(fd.get('actualDep')||'');r.stops[f.dataset.index]={actualArr,actualDep};if((actualArr||actualDep)&&r.status==='scheduled')r.status='running';s.updatedAt=new Date().toISOString();persist();closeModal();render();toast('Actual times saved.');return}}
window.addEventListener('hashchange',()=>{draft=null;draftId=null;render();window.scrollTo(0,0)});
document.addEventListener('click',onClick);
document.addEventListener('change',onChange);
document.addEventListener('input',onInput);
document.addEventListener('submit',onSubmit);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
})();
